# Legacy Archive Adapter demo: protocol + schema bridging with caching.
LEGACY_DB={"42":"TITLE|Solar Sails|YEAR|2019"}  # pipe-delimited legacy wire format
CACHE={}
def legacy_fetch(key):
    if key in CACHE: return dict(CACHE[key],cached=True)
    raw=LEGACY_DB.get(key)
    if not raw: return {"error":"not found","code":404}
    parts=raw.split("|"); rec=dict(zip(parts[::2],[int(x) if x.isdigit() else x for x in parts[1::2]]))
    modern={"id":key,"title":rec["TITLE"],"year":rec["YEAR"],"cached":False}
    CACHE[key]=modern; return modern
print(legacy_fetch("42")); print(legacy_fetch("42")); print(legacy_fetch("99"))

